arguments.keystrokes:
cat << 'EOF' > test_spill_details.py
import flowio
import glob, os

for f in sorted(glob.glob('/task/input/fcs/*.fcs')):
    fo = flowio.FlowData(f)
    # Check all keywords in text
    interesting = {}
    for k, v in fo.text.items():
        if any(w in k.lower() for w in ['spill', 'comp', 'matrix', 'creator', 'software']): 
            interesting[k] = v
    print(os.path.basename(f), interesting.get('$cyt', ''), interesting.get('spillover') is not None)
EOF
python3 test_spill_details.py

